const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d');let data,boards=[];
function geometryEqual(a,b,label){const visit=(x,y,p)=>{if(typeof x==='number'&&typeof y==='number'){if(!Number.isFinite(x)||!Number.isFinite(y)||Math.abs(x-y)>1e-10)throw Error(label+' coordinate '+p);return;}if(x&&y&&typeof x==='object'&&typeof y==='object'){same(Object.keys(x).sort(),Object.keys(y).sort(),label+' structure '+p);for(const k of Object.keys(x))visit(x[k],y[k],p+'.'+k);}else if(x!==y)throw Error(label+' '+p);};visit(a,b,'root');}
function text(s,x,y,size=20,color='#d0e3ef'){ctx.fillStyle=color;ctx.font=`${size}px sans-serif`;ctx.fillText(s,x,y);}
function wrap(s,x,y,w,size=18){ctx.font=`${size}px sans-serif`;let line='',n=0;for(const c of s){if(ctx.measureText(line+c).width>w){text(line,x,y+n*25,size);line=c;n++;}else line+=c;}if(line)text(line,x,y+n*25,size);return n+1;}
function verifyWheel(b,f,label){const p=b.model.flow.physics,m=p.mechanisms[0],s=b.wheels?.[0]?.sprite,r=f.mechanisms[0];if(!s||b.wheels.length!==1)throw Error('Actual windmill Sprite missing');if(m.x!==64||m.y!==476.5||s.x!==m.x||s.y!==m.y||r.x!==m.x||r.y!==m.y||s.anchor.x!==.5||s.anchor.y!==.5||s.scale.x!==1/3||s.scale.y!==1/3)throw Error('Windmill factory/raw/Sprite center or transform mismatch');if(m.angle!==r.angle||m.omega!==r.omega)throw Error('Actual renderer angle differs from saved sample');let frontPlate=null;if((m.shapeProfile??'legacy-capsules')==='photo-three-vane'){const plate=b.wheels[0].plateSprite,order=b.wheels[0].layerOrder();if(!plate||plate.x!==m.x||plate.y!==m.y||plate.anchor.x!==.5||plate.anchor.y!==.5||plate.scale.x!==1/3||plate.scale.y!==1/3||!(order.rotor<order.balls&&order.balls<order.plate))throw Error('Actual separate plate center/transform/depth differs');frontPlate={center:{x:plate.x,y:plate.y},anchor:{x:plate.anchor.x,y:plate.anchor.y},scale:{x:plate.scale.x,y:plate.scale.y},layerOrder:order};}else if(b.wheels[0].plateSprite)throw Error('Legacy hierarchy changed');const actual=windmillContactGeometry(m),recorded=windmillContactGeometry(r);same(actual,recorded,'Actual solver geometry differs from frame profile/angle');return {label,profile:actual.profile,center:{x:s.x,y:s.y},angle:m.angle,omega:m.omega,frontPlate,contactGeometry:actual};}
window.s8WheelReview={canvas,async load(input){if(data||input.cases?.length!==2)throw Error('Reload for another pair');if(!input.status||input.status.length>80)throw Error('Explicit current selection/adoption status required');data=input;const geometry=[];try{for(const c of input.cases){const host=document.createElement('div');host.className='source';host.innerHTML='<div id="canvas"></div>';document.querySelector('.sources').append(host);let model,wheels;const api=await mountBoard(host,{production:true,trialReplay:true,flowOptions:c.run.flowOptions,reviewHook:v=>{model=v.model;wheels=v.windmillViews;}});const b={api,host,model,wheels,c};boards.push(b);api.setSound(false);api.setView('board');const p=model.flow.physics;same(p.pins,c.run.pins,'101 renderer pins');for(const k of ['ballRadius','colliders','pockets','mechanisms','outlet','launchExit','launchSpeedOffset','gate','rightChucker','returnOutlet','separateLaunchPlane'])geometryEqual(p[k],c.run.fixed[k],'Factory fixed '+k);if(p.colliders.some(c=>c.role==='heso-guide'))throw Error('Tray contact still present');same({ballRadius:p.ballRadius,displayBallScale:p.displayBallScale,displayBallDiameter:p.displayBallDiameter??null,textureExtent:28,spriteScaleDivisor:3,spriteBoundingDiameter:28*p.displayBallScale/3},c.run.display,'Default ball display');geometry.push({id:c.run.config.id,initialWheel:verifyWheel(b,{mechanisms:c.run.fixed.mechanisms},'initial factory'),pins:p.pins,fixed:c.run.fixed,display:c.run.display,camera:PLAY_CAMERA});}}catch(e){this.dispose();throw e;}return geometry;},
paint(time,{view='whole',endpoint=null,ballId=null,showContact=false}={}){
 if(!data||!['whole','near','results'].includes(view)||!Number.isFinite(time)||time<0||(!endpoint&&time>data.duration+1e-8))throw Error('Outside common actual record');
 if(endpoint&&!['stop','end'].includes(endpoint))throw Error('Unknown actual endpoint');ctx.fillStyle='#071421';ctx.fillRect(0,0,1280,1080);text(view==='results'?'風車形状1案：全時間の実結果':'風車形状だけを比較：両側ともヘソガイドなし',24,42,29,'#fff');text('元101釘・左上狙い・強度0.18・球/物理/風車中心と回転係数・レール/口20は固定',24,77,19);text(data.status,24,108,20);const receipts=[];
 if(view==='results'){
  const rows=boards.map(b=>b.c.run);const labels=['実発射','ヘソ','一般','OUT','返却','残球','滞留','液晶・全層中心','液晶・全層半径のみ','液晶・前面中心','液晶・前面半径のみ'];const vals=r=>[r.physical.shots,r.end.counts.start,r.end.counts.normal,r.end.counts.out,r.end.counts.returned,r.end.remaining,r.endDiagnostics.stalled,r.lcdIntrusion.centreBallIds.length,r.lcdIntrusion.boundaryOnlyBallIds.length,r.lcdIntrusion.frontCentreBallIds.length,r.lcdIntrusion.frontBoundaryOnlyBallIds.length];
  text(`今回の開始条件：${data.phase}／実250発停止＋45秒排出`,24,165,24,'#fff');text('比較',24,225,22);text('変更前・旧風車接触',440,225,23);text('修正案・共有輪郭',840,225,23);labels.forEach((label,j)=>{text(label,24,270+j*45,22,'#fff');text(String(vals(rows[0])[j]),470,270+j*45,25);text(String(vals(rows[1])[j]),870,270+j*45,25);});
  wrap('各側の実終端：'+rows.map(r=>r.end.time.toFixed(6)+'秒').join('／')+'。30Hz通常列の最終時刻とは別です。',24,790,1210,19);wrap('この表は指定した開始条件1組の全結果です。750発・ヘソ60以上と各条件非悪化の合否を、この短い1条件だけでは確定しません。',24,850,1210,20);text('ガイド付き旧15/250は別条件の履歴。今回の基準へ置き換えません。',24,945,19);return {view,sourceSHA:data.sourceSHA,phase:data.phase,results:rows.map(r=>({id:r.config.id,counts:r.end.counts,shots:r.physical.shots,remaining:r.end.remaining,time:r.end.time}))};
 }
 for(let i=0;i<boards.length;i++){
  const b=boards[i],r=b.c.run,s=endpoint?{index:null,frame:r.replayEndpoints[endpoint]}:sample(r,time),f=s.frame,x=24+i*632;b.api.applyTrialFrame(f);const wheel=verifyWheel(b,f,'actual frame '+(endpoint??s.index)),snap=b.api.snapshot();same(snap.counts,f.counts,'Actual frame counts');if(snap.spawned!==f.spawned||snap.inFlight!==f.inFlight)throw Error('Actual frame mass differs');
  text(r.config.label,x,152,24,'#fff');text(`実時刻${f.time.toFixed(6)}秒／開始条件${r.phase}／速度1.0`,x,188,19);if(endpoint)text(`各側の実${endpoint==='stop'?'停止':'終端'}snapshot・通常30Hzとは別`,x,213,17);
  const crop=view==='near'?{x:20,y:270,w:100,h:100}:{x:0,y:0,w:396,h:436},scale=Math.min(600/crop.w,690/crop.h),w=crop.w*scale,h=crop.h*scale,dx=x+(600-w)/2,dy=230+(690-h)/2;
  ctx.drawImage(b.api.canvas,crop.x*b.api.canvas.width/396,crop.y*b.api.canvas.height/436,crop.w*b.api.canvas.width/396,crop.h*b.api.canvas.height/436,dx,dy,w,h);
  const project=p=>({x:dx+(p.x*PLAY_CAMERA.scale+PLAY_CAMERA.x-crop.x)*scale,y:dy+(p.y*PLAY_CAMERA.scale+PLAY_CAMERA.y-crop.y)*scale});ctx.save();ctx.beginPath();ctx.rect(dx,dy,w,h);ctx.clip();
  if(ballId!==null){const ball=f.balls.find(p=>p.id===ballId);if(ball){const p=project(ball);ctx.strokeStyle='#ffe6a2';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(5,ball.r*scale+3),0,Math.PI*2);ctx.stroke();}}
  if(showContact){ctx.strokeStyle='#91e4f2';ctx.lineWidth=1;for(const e of wheel.contactGeometry.boundary??[]){ctx.beginPath();if(e.type==='arc'){const c=project(e.centre);ctx.arc(c.x,c.y,e.radius*scale,e.startAngle,e.endAngle);}else{const a=project(e.a),z=project(e.b);ctx.moveTo(a.x,a.y);ctx.lineTo(z.x,z.y);}ctx.stroke();}for(const c of wheel.contactGeometry.capsules??[]){const a=project(c.a),z=project(c.b);ctx.lineWidth=c.r*2*scale;ctx.lineCap='round';ctx.globalAlpha=.3;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(z.x,z.y);ctx.stroke();ctx.globalAlpha=1;}}
  ctx.restore();text(`発射${f.spawned}／ヘソ${f.counts.start}／一般${f.counts.normal}／OUT${f.counts.out}`,x,954,20);text(`返却${f.counts.returned}／残球${f.inFlight}／角${wheel.angle.toFixed(6)}`,x,983,19);
  if(ballId!==null){const outcome=r.events.find(e=>e.type==='outcome'&&e.ballId===ballId);text(`同球ID${ballId}の実終点：${outcome?.kind??'残球'}／${outcome?.time?.toFixed(6)??'未終端'}秒`,x,1010,17);}
  receipts.push({id:r.config.id,index:s.index,requestedTime:endpoint?null:time,actualTime:f.time,endpoint,view,crop,pixelsPerInternalUnit:scale,counts:f.counts,spawned:f.spawned,inFlight:f.inFlight,ballId,actualTrackedBall:f.balls.find(p=>p.id===ballId)??null,wheel});
 }
 text('保存した実30Hz座標・層・角度／1倍・補間/物理再計算なし。内部単位（mm未校正）。',24,1056,18);return receipts;
},dispose(){for(const b of boards){b.api.dispose();b.host.remove();}boards=[];data=null;}};
